<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import type {components} from '@ism/api-client';
import {useSessionStore} from '../stores/session';
const session=useSessionStore();type Type=components['schemas']['DictionaryType'];type Item=components['schemas']['DictionaryItem'];type Save=components['schemas']['UpsertDictionaryItem'];
const types=ref<Type[]>([]),code=ref(''),current=ref<Type>(),loading=ref(false),busy=ref(false),unknown=ref(false),stale=ref(false),error=ref(''),notice=ref(''),box=ref<HTMLElement>();
const mode=ref<'item'|'name'|'remove'|'restoreName'>(),editing=ref<Item>(),name=ref('');
const item=reactive<Save>({code:'',label:'',value:'',sortOrder:10,status:'ACTIVE',version:0});
const locked=computed(()=>loading.value||busy.value||unknown.value),canWrite=computed(()=>!!current.value?.canManage&&!stale.value&&!locked.value);
const sources:Record<string,string>={SYSTEM:'系统继承',TENANT_OVERRIDE:'租户覆盖',TENANT_CUSTOM:'租户自定义',TENANT_REMOVED:'已移除（保留版本）'};
type Attempt=({kind:'item';body:Save;itemCode:string}|{kind:'name';body:components['schemas']['UpdateDictionaryName']}|{kind:'remove';itemCode:string;version:number}|{kind:'restoreName';version:number})&{key:string;typeCode:string};let attempt:Attempt|null=null,alive=true;
watch(error,async v=>{if(v){await nextTick();box.value?.focus();}});
function apply(value:Type){current.value=value;types.value=types.value.map(t=>t.code===value.code?value:t);stale.value=false;}
async function load(){if(locked.value)return;loading.value=true;error.value='';current.value=undefined;types.value=[];mode.value=undefined;try{const r=await session.client.GET('/configuration/dictionaries');if(!alive)return;if(r.error){error.value=r.error.error.message;return;}types.value=r.data.data;if(!types.value.some(t=>t.code===code.value))code.value=types.value[0]?.code??'';current.value=types.value.find(t=>t.code===code.value);stale.value=false;}catch{if(alive)error.value='字典读取失败，请重试';}finally{if(alive)loading.value=false;}}
async function detail(){if(locked.value||!code.value)return;loading.value=true;error.value='';current.value=undefined;mode.value=undefined;try{const r=await session.client.GET('/configuration/dictionaries/{typeCode}',{params:{path:{typeCode:code.value}}});if(!alive)return;if(r.error)error.value=r.error.error.message;else apply(r.data.data);}catch{if(alive)error.value='字典详情读取失败，请重试';}finally{if(alive)loading.value=false;}}
function edit(row?:Item){if(!canWrite.value)return;editing.value=row;Object.assign(item,row?{code:row.code,label:row.label,value:row.value,sortOrder:row.sortOrder,status:row.source==='TENANT_REMOVED'?'ACTIVE':row.status,version:row.version}:{code:'',label:'',value:'',sortOrder:10,status:'ACTIVE',version:0});mode.value='item';error.value='';}
function rename(){if(!canWrite.value)return;name.value=current.value?.name??'';mode.value='name';}
function submit(){if(!canWrite.value||!current.value||!mode.value)return;const common={key:crypto.randomUUID(),typeCode:current.value.code};
 if(mode.value==='item'){if(!/^[A-Z][A-Z0-9_]{1,63}$/.test(item.code)||!item.label.trim()||!item.value.trim()){error.value='请填写有效条目代码、显示名称和取值';return;}attempt={...common,kind:'item',itemCode:item.code,body:{...item}};}
 else if(mode.value==='name'){if(!name.value.trim()){error.value='字典名称不能为空';return;}attempt={...common,kind:'name',body:{name:name.value.trim(),version:current.value.nameVersion??0}};}
 else if(mode.value==='remove'&&editing.value)attempt={...common,kind:'remove',itemCode:editing.value.code,version:editing.value.version};
 else if(mode.value==='restoreName')attempt={...common,kind:'restoreName',version:current.value.nameVersion??0};else return;void send();}
async function send(){if(!attempt||busy.value)return;const a=attempt,wasUnknown=unknown.value;busy.value=true;error.value='';notice.value='';try{const h={'Idempotency-Key':a.key};const r=a.kind==='item'?await session.client.PUT('/configuration/dictionaries/{typeCode}/items/{itemCode}',{params:{path:{typeCode:a.typeCode,itemCode:a.itemCode},header:h},body:a.body}):a.kind==='name'?await session.client.PUT('/configuration/dictionaries/{typeCode}/name',{params:{path:{typeCode:a.typeCode},header:h},body:a.body}):a.kind==='remove'?await session.client.DELETE('/configuration/dictionaries/{typeCode}/items/{itemCode}',{params:{path:{typeCode:a.typeCode,itemCode:a.itemCode},header:h,query:{version:a.version}}}):await session.client.DELETE('/configuration/dictionaries/{typeCode}/name',{params:{path:{typeCode:a.typeCode},header:h,query:{version:a.version}}});
 if(!alive)return;if(r.error){unknown.value=wasUnknown||r.response.status>=500;error.value=unknown.value?'结果尚未确认，请使用原请求重试；权限变化时请联系管理员核对':r.error.error.message;if(!unknown.value){attempt=null;if(r.response.status===409){stale.value=true;error.value+='，请重新读取后核对版本';}}return;}
 if(!r.data?.success)throw Error('Unknown receipt');attempt=null;unknown.value=false;mode.value=undefined;notice.value='字典操作回执已收到，仅影响本租户；正在核对当前状态。';
 try{const latest=await session.client.GET('/configuration/dictionaries/{typeCode}',{params:{path:{typeCode:a.typeCode}}});if(!alive)return;if(latest.error){stale.value=true;error.value='操作已收到回执，但当前状态读取失败，请重新读取，勿重复提交';}else{apply(latest.data.data);notice.value='字典已保存并核对当前状态，仅影响本租户。';}}catch{if(alive){stale.value=true;error.value='操作已收到回执，但当前状态读取失败，请重新读取，勿重复提交';}}
 }catch{if(alive){unknown.value=true;error.value='结果尚未确认，请使用原请求重试，勿重复提交';}}finally{if(alive)busy.value=false;}}
onMounted(()=>void load());onBeforeUnmount(()=>{alive=false;attempt=null;});
</script>
<template><section class="dictionary-page" aria-label="租户字典管理"><h1>字典管理</h1><p>继承系统字典，在本租户覆盖显示名称、排序和启停。系统代码与系统取值保持不变；自定义条目不改变已有业务枚举或状态机。</p><p v-if="error" ref="box" role="alert" tabindex="-1">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<div class="actions"><el-button :disabled="locked" @click="load">重新读取字典目录</el-button><el-button :disabled="locked||!code" @click="detail">重新读取当前字典</el-button></div><p v-if="loading" role="status">正在读取字典…</p>
<el-form label-position="top"><el-form-item label="选择字典"><el-select v-model="code" aria-label="选择字典" :disabled="locked" @change="detail"><el-option v-for="t in types" :key="t.code" :value="t.code" :label="`${t.name}（${t.code}）`"/></el-select></el-form-item></el-form><p v-if="!loading&&!types.length">当前未加载到字典目录，请核对权限或重试。</p>
<el-card v-if="current" shadow="never"><h2>{{current.name}} · {{current.code}}</h2><p>名称来源：{{sources[current.nameSource??'SYSTEM']}}；名称版本：{{current.nameVersion??0}}。系统名称：{{current.systemName??current.name}}。</p><p v-if="!current.canManage">当前账号只读，不能修改字典。</p><div class="actions"><el-button :disabled="!canWrite" @click="rename">自定义字典名称</el-button><el-button v-if="current.nameSource==='TENANT_OVERRIDE'" :disabled="!canWrite" @click="mode='restoreName'">恢复系统名称</el-button><el-button v-if="current.tenantExtensible" :disabled="!canWrite" @click="edit()">新增自定义条目</el-button></div>
<div class="table-scroll"><table><thead><tr><th>代码</th><th>显示名称</th><th>取值</th><th>排序</th><th>条目启停</th><th>来源 / 版本</th><th>操作</th></tr></thead><tbody><tr v-for="row in current.items" :key="row.code"><td>{{row.code}}</td><td>{{row.label}}</td><td>{{row.value}}</td><td>{{row.sortOrder}}</td><td>{{row.status==='ACTIVE'?'启用':'停用'}}</td><td>{{sources[row.source]}} / {{row.version}}</td><td><el-button :disabled="!canWrite" @click="edit(row)">编辑条目</el-button><el-button v-if="row.source!=='SYSTEM'" :disabled="!canWrite" @click="editing=row;mode='remove'">{{row.source==='TENANT_CUSTOM'?'移除自定义':'恢复继承'}}</el-button></td></tr><tr v-if="!current.items.length"><td colspan="7">没有有效字典条目。</td></tr></tbody></table></div>
<details v-if="current.removedItems?.length"><summary>已移除自定义条目（保留历史版本）</summary><ul><li v-for="row in current.removedItems" :key="row.code">{{row.code}} · {{row.label}} · 版本 {{row.version}} <el-button :disabled="!canWrite" @click="edit(row)">重新启用自定义</el-button></li></ul></details>
<el-form v-if="mode" label-position="top" class="editor" @submit.prevent="submit"><h3>{{mode==='item'?'编辑字典条目':mode==='name'?'设置本租户字典名称':mode==='remove'?'确认移除覆盖或自定义':'确认恢复系统名称'}}</h3>
<template v-if="mode==='item'"><el-form-item label="条目代码"><el-input v-model="item.code" aria-label="条目代码" :maxlength="64" :disabled="locked||!!editing"/></el-form-item><el-form-item label="显示名称"><el-input v-model="item.label" aria-label="显示名称" :maxlength="100" :disabled="locked"/></el-form-item><el-form-item label="条目取值"><el-input v-model="item.value" aria-label="条目取值" :maxlength="200" :disabled="locked||!!editing&&editing.source!=='TENANT_CUSTOM'&&editing.source!=='TENANT_REMOVED'"/></el-form-item><p v-if="editing?.source==='SYSTEM'||editing?.source==='TENANT_OVERRIDE'">系统代码和取值不可变；如历史覆盖取值不符合当前系统标准，请先恢复继承。</p><el-form-item label="排序"><el-input-number v-model="item.sortOrder" aria-label="排序" :disabled="locked"/></el-form-item><el-form-item label="启停状态"><el-select v-model="item.status" aria-label="启停状态" :disabled="locked"><el-option value="ACTIVE" label="启用"/><el-option value="DISABLED" label="停用"/></el-select></el-form-item></template>
<el-form-item v-else-if="mode==='name'" label="本租户字典名称"><el-input v-model="name" aria-label="本租户字典名称" :maxlength="100" :disabled="locked"/></el-form-item>
<p v-else>仅移除本租户覆盖：系统项恢复系统定义，自定义项退出有效列表。历史版本保留，旧请求不能覆盖后续配置；不修改业务历史数据或其他租户。</p>
<div class="actions"><el-button type="primary" native-type="submit" :disabled="!canWrite">确认字典操作</el-button><el-button :disabled="locked" @click="mode=undefined">取消编辑</el-button></div></el-form></el-card>
<el-button v-if="unknown" :disabled="busy" @click="send">使用原请求重试字典操作</el-button></section></template>
<style scoped>.dictionary-page{max-width:1180px;min-width:0;color:var(--ism-text-primary,#172b42)}h1{font-size:24px}h2{font-size:20px}p,li{line-height:1.7;overflow-wrap:anywhere}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.actions .el-button{margin-left:0}.el-select{width:100%;max-width:520px}.table-scroll{max-width:100%;overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--ism-border,#dce4ed)}th{background:var(--ism-bg-muted,#f3f6fa)}td .el-button{margin:4px}.editor{max-width:650px;margin-top:20px}summary{cursor:pointer;padding:12px 0;min-height:44px;box-sizing:border-box}[role=alert]{color:var(--ism-danger,#b42332);border:1px solid currentColor;border-radius:6px;padding:12px}:deep(.el-input__inner){font-size:16px}</style>
